import{_ as r,o as t,c as o,ag as e}from"./chunks/framework.CukOUUOK.js";const c=JSON.parse('{"title":"繁荣的悖论：巴列维伊朗为什么越改革越危险","description":"引言：一个反直觉的历史谜题 1978年，伊朗是中东最富裕的国家之一。 它的GDP总量位居世界第九，人均收入在不到二十年间增长了约14倍；石油繁荣最疯狂的那几年，名义经济增速一度冲到16%—17%，远超同期日本的约4%和韩…","frontmatter":{"title":"繁荣的悖论：巴列维伊朗为什么越改革越危险","categories":"威权与转型","tags":["权力","制度","劳动与经济","历史"],"description":"引言：一个反直觉的历史谜题 1978年，伊朗是中东最富裕的国家之一。 它的GDP总量位居世界第九，人均收入在不到二十年间增长了约14倍；石油繁荣最疯狂的那几年，名义经济增速一度冲到16%—17%，远超同期日本的约4%和韩…","date":"2026-09-15T12:00:00.000Z","series":"改革的代价_伊朗五十年五论","seriesOrder":1},"headers":[],"relativePath":"posts/2026-09-15-prosperity-paradox-pahlavi-iran.md","filePath":"posts/2026-09-15-prosperity-paradox-pahlavi-iran.md","lastUpdated":1789992797000}'),n={name:"posts/2026-09-15-prosperity-paradox-pahlavi-iran.md"};function s(p,a,l,i,h,g){return t(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="繁荣的悖论-巴列维伊朗为什么越改革越危险" tabindex="-1">繁荣的悖论：巴列维伊朗为什么越改革越危险 <a class="header-anchor" href="#繁荣的悖论-巴列维伊朗为什么越改革越危险" aria-label="Permalink to &quot;繁荣的悖论：巴列维伊朗为什么越改革越危险&quot;">​</a></h1><h3 id="引言-一个反直觉的历史谜题" tabindex="-1">引言：一个反直觉的历史谜题 <a class="header-anchor" href="#引言-一个反直觉的历史谜题" aria-label="Permalink to &quot;引言：一个反直觉的历史谜题&quot;">​</a></h3><p>1978年，伊朗是中东最富裕的国家之一。</p><p>它的GDP总量位居世界第九，人均收入在不到二十年间增长了约14倍；石油繁荣最疯狂的那几年，名义经济增速一度冲到16%—17%，远超同期日本的约4%和韩国的约8%。石油年收入从40亿美元暴涨至200多亿美元，国库充盈到足以支撑每年上百亿美元的军费开支。德黑兰被称作”中东的巴黎”，女性穿着迷你裙走在街头，大学校园里女生比例达到35%，高速公路和摩天大楼拔地而起。</p><p>然而仅仅一年后，这个看起来不可战胜的王朝就被一场全民革命彻底推翻。</p><p>这不是一个”穷则生变”的故事。恰恰相反，它是一个”富则生变”的故事——而且正是那些看起来最令人振奋的改革成就，在特定的制度条件下，变成了加速王朝崩溃的催化剂。</p><p>这个悖论值得每一个关心”改革”与”稳定”关系的人深思。</p><h3 id="第一章-天降财富与一个国王的野心" tabindex="-1">第一章：天降财富与一个国王的野心 <a class="header-anchor" href="#第一章-天降财富与一个国王的野心" aria-label="Permalink to &quot;第一章：天降财富与一个国王的野心&quot;">​</a></h3><h3 id="_1953-一切的起点" tabindex="-1">1953：一切的起点 <a class="header-anchor" href="#_1953-一切的起点" aria-label="Permalink to &quot;1953：一切的起点&quot;">​</a></h3><p>要理解巴列维的改革，必须先理解他权力的来源——因为它从一开始就带着原罪。</p><p>1951年，伊朗民选首相摩萨台推动石油国有化，将英国控制的英伊石油公司收归国有。这在伊朗国内获得了压倒性的民意支持。但英国不答应，美国更不答应——冷战背景下，艾森豪威尔政府担心伊朗倒向苏联。于是CIA和英国军情六处联合策划了代号”阿贾克斯行动”的政变，在1953年8月19日推翻了摩萨台，扶植巴列维国王重掌大权。</p><p>政变之后，美国石油公司获得了伊朗40%的石油开采权，CIA协助巴列维建立了秘密警察机构”萨瓦克”（SAVAK）。从这一刻起，巴列维的王权就背负着双重枷锁：<strong>对外，他是美国在中东的代理人；对内，他的合法性永远无法摆脱”政变产物”的标签。</strong></p><h3 id="石油红利-改变一切的变量" tabindex="-1">石油红利：改变一切的变量 <a class="header-anchor" href="#石油红利-改变一切的变量" aria-label="Permalink to &quot;石油红利：改变一切的变量&quot;">​</a></h3><p>1963年，巴列维启动了他雄心勃勃的”白色革命”。但真正改变游戏规则的，是1973年的石油危机。</p><p>这一年，伊朗从西方石油财团手中收回石油主权，恰逢国际油价从3美元/桶暴涨至12美元/桶。伊朗石油年收入从1972年的28亿美元骤升至1974年的178亿美元，石油收入占财政比重从42%飙升至74%。</p><p>这笔无需本土产业支撑的”天降财富”，彻底颠覆了巴列维的决策逻辑。此前他的改革仍需兼顾财政平衡与本土产业发展，而石油美元填满国库后，他形成了一种偏执认知：<strong>只要有石油美元，就能一步实现现代化。</strong> 无需本土资本积累，无需兼顾产业造血，无需平衡阶层利益——钱能解决一切。</p><p>正是在这种逻辑驱动下，他制定了一个又一个令人瞠目的计划：第五个五年计划的投资额从365亿美元追加至700亿美元，目标是让伊朗在十年内成为”世界第五大工业国和军事强国”。</p><h3 id="被切断的链条-食利国家与-不必负责-的权力" tabindex="-1">被切断的链条：食利国家与”不必负责”的权力 <a class="header-anchor" href="#被切断的链条-食利国家与-不必负责-的权力" aria-label="Permalink to &quot;被切断的链条：食利国家与”不必负责”的权力&quot;">​</a></h3><p>这里需要一个更锋利的分析工具。政治经济学里有个专门描述这类国家的概念——<strong>食利国家（rentier state）</strong>。它的核心机制一句话就能说清：</p><blockquote><p>当国家的收入主要来自地租（石油），而不是税收，它就绕开了”无代表不纳税”这条问责链条。国家不必向社会要钱，也就不必向社会负责；社会无法通过财政谈判施加压力，就只能通过街头施加压力。</p></blockquote><p>巴列维的伊朗几乎是这一模型最标准的样本。石油美元直接流入国库，不经过纳税人这一环，国王因此可以拥有一个”不需要与社会协商”的政府：不需要议会真正审议预算，不需要向地方让渡权力，不需要对新兴阶层的要求做出制度性回应。</p><p><strong>这正是理解整篇文章的关键：石油不仅给了巴列维钱，还给了他”不必让步”的底气。</strong> 财富在这里不是改革的助力，而是政治开放的替代品。</p><h3 id="第二章-三条改革线的错位" tabindex="-1">第二章：三条改革线的错位 <a class="header-anchor" href="#第二章-三条改革线的错位" aria-label="Permalink to &quot;第二章：三条改革线的错位&quot;">​</a></h3><p>巴列维的改革可以拆解为三条并行的线索：经济现代化、政治威权化、文化激进世俗化。每一条单独看都有其逻辑，但三者之间的<strong>张力</strong>才是致命的。</p><h3 id="经济线-国家垄断下的-无分配增长" tabindex="-1">经济线：国家垄断下的”无分配增长” <a class="header-anchor" href="#经济线-国家垄断下的-无分配增长" aria-label="Permalink to &quot;经济线：国家垄断下的”无分配增长”&quot;">​</a></h3><h3 id="成就确实惊人" tabindex="-1">成就确实惊人 <a class="header-anchor" href="#成就确实惊人" aria-label="Permalink to &quot;成就确实惊人&quot;">​</a></h3><p>白色革命的核心措施包括：土地改革（将大地主占有的土地重新分配给农民）、赋予妇女选举权、工人利润分享计划、国有企业私有化、组建”知识大军”赴农村扫盲。到1977年，小学入学人数从1960年的27万增至超过1000万，文盲率从85%降至55%，65%以上人口拥有住房。</p><p>1963至1977年间，伊朗建立起涵盖冶金、汽车、化工、电子及原子能发电的完整工业体系，制造业占GDP比例从11%升至17%。</p><h3 id="但繁荣是少数人的特权" tabindex="-1">但繁荣是少数人的特权 <a class="header-anchor" href="#但繁荣是少数人的特权" aria-label="Permalink to &quot;但繁荣是少数人的特权&quot;">​</a></h3><p>问题在于，这些辉煌的数字背后，是触目惊心的分配不公。</p><p>根据1973—1974年的城市家庭支出调查，<strong>最富有的20%人口占总支出的55.5%，而最贫穷的20%仅占3.7%</strong>。国际劳工组织的一份报告据此判定，伊朗是”世界上最不平等的社会之一”，而且这种不平等在1960年代变得更加严重。</p><p>1976年的基尼系数高达47.9，最富10%人口控制全国40%以上财富，最穷40%人口仅占不到15%。巴列维家族积累的财富占当时GDP的10%以上。</p><p>石油美元并没有用于公共服务和普及基础设施，而主要是在宫廷、关联公司和接近权力中心的封闭网络中流转。用西方经济学家的话说，这是典型的“<strong>无分配的增长</strong>”。</p><h3 id="土地改革的悖论" tabindex="-1">土地改革的悖论 <a class="header-anchor" href="#土地改革的悖论" aria-label="Permalink to &quot;土地改革的悖论&quot;">​</a></h3><p>白色革命中最具讽刺意味的是土地改革。表面上，约250万农户获得了土地。但实际上，农民分到的只是不可自由买卖、不可抵押、不可扩展的碎片化土地使用权，人均仅3—4亩，且多为中低质量土地。</p><p>更要命的是，地主消失的同时也带走了资金和管理能力。伊朗农业千百年来依赖的坎儿井——一种复杂的地下灌溉系统——需要持续维护和巨额投入，地主消失后无人承担，坎儿井迅速淤塞干涸。农民空有土地，却因缺乏灌溉水源而无法耕种。</p><p>与此同时，巴列维大量进口美国小麦以维持城市稳定，进口小麦价格仅为国产小麦的一半。伊朗农民在破碎的、缺水的土地上卖命换来的粮食，根本竞争不过廉价进口粮。种地不赚钱反而亏本，农民只能卖地或抛荒，涌入城市。</p><p>从1963年到1978年，伊朗农村人口占比从约70%暴跌至约46%（城市化率相应从约30%升至约54%），数百万破产农民像潮水一样涌入德黑兰等大城市。但他们没有城市需要的技能，只能挤在城市边缘的铁皮棚户区里。到1975年前后，约45%的城市人口生活在棚户区，德黑兰50%的人口挤在仅占城市面积20%的贫民区。</p><p>正如学者亚伯拉罕米安所写：<strong>“石油繁荣给中产阶级带来了体面的住房、小汽车和每年去欧洲旅行。但它给穷人带来的，只是使贫困现代化了。”</strong></p><h3 id="政治线-从威权到极权的加速滑落" tabindex="-1">政治线：从威权到极权的加速滑落 <a class="header-anchor" href="#政治线-从威权到极权的加速滑落" aria-label="Permalink to &quot;政治线：从威权到极权的加速滑落&quot;">​</a></h3><h3 id="政治空间的系统性压缩" tabindex="-1">政治空间的系统性压缩 <a class="header-anchor" href="#政治空间的系统性压缩" aria-label="Permalink to &quot;政治空间的系统性压缩&quot;">​</a></h3><p>巴列维的政治控制并非线性加强，而是有一个明显的阶段性转折。</p><p>1953年政变后到1963年白色革命启动前，巴列维虽然依靠军方和萨瓦克维持权力，但仍保留了议会的形式运作和两党制的表面框架。白色革命启动后，他把权力进一步收拢到两个御用政党手中，议会的实际功能只剩橡皮图章，政治空间开始收窄。</p><p><strong>真正的转折点是1975年。</strong> 这一年，巴列维做了一件极其关键的事——<strong>取缔一切政党，建立唯一的御用政党”伊朗复兴党”（Rastakhiz）</strong>，要求所有成年人加入，公开宣称”一个国家、一个国王、一个政党”，声称”不入党，就离开这个国家”。</p><p>复兴党在1975年6月的议会选举中”获得了”全部268个席位，所有候选人必须宣誓”对君主制政权的忠诚”和”对白色革命的忠诚”。政治公共空间被压缩至零点。</p><p>这个时间点的选择极其致命——恰恰是在经济因石油价格暴涨而达到顶峰、社会矛盾因通胀和分配不公而最尖锐的时刻。</p><h3 id="萨瓦克-恐惧的工业化生产" tabindex="-1">萨瓦克：恐惧的工业化生产 <a class="header-anchor" href="#萨瓦克-恐惧的工业化生产" aria-label="Permalink to &quot;萨瓦克：恐惧的工业化生产&quot;">​</a></h3><p>与一党制配套的是萨瓦克——伊朗的秘密警察机构。1957年由CIA和以色列摩萨德协助建立，巅峰时期雇员约1.5万人（不同来源估计在7000至15000之间），另有数万名线人，渗透政府、军队、媒体、大学及宗教场所。</p><p>萨瓦克的酷刑手段令人发指：电击生殖器、烧红烙铁按在囚犯身上、碎玻璃灌肛、水刑、模拟处决、长期单独监禁导致精神崩溃……这些不是道听途说，而是国际人权组织和美国外交官的记录。</p><p>1976年一年，被逮捕或拘留者数以万计（不同来源统计口径不一，从2.5万到10万不等）。整个1970年代，仅三年间就有约25万人被送进监狱、8万人流放，超过万人因政治罪名被处决或失踪。国际特赦组织1976年报告称，伊朗关押的政治犯数量几乎超过世界上任何国家。</p><p>最能说明问题的是影响了整整一代青年的伊斯兰现代主义思想家<strong>阿里·沙里亚提</strong>——他的演讲录音在大学里秘密流传，被视为革命的思想火种之一。他多次遭萨瓦克监禁，1977年流亡英国后离奇死亡，年仅43岁。</p><p><strong>政治空间的窒息意味着不满情绪无法通过任何合法渠道表达，只能转向地下宗教网络、秘密磁带和清真寺的布道坛。</strong></p><h3 id="文化线-激进世俗化的文化战争" tabindex="-1">文化线：激进世俗化的文化战争 <a class="header-anchor" href="#文化线-激进世俗化的文化战争" aria-label="Permalink to &quot;文化线：激进世俗化的文化战争&quot;">​</a></h3><p>巴列维在文化和社会层面的改革是激进的、强制性的：</p><ul><li>废除伊斯兰教法法庭，建立世俗司法体系</li><li>将宗教基金（瓦克夫）收归国有，严重损害教士阶层的经济基础</li><li>禁止宗教人士穿传统服饰进入政府机构</li><li>将历法从伊斯兰历改为”帝王历”（以居鲁士大帝登基为元年），公元1976年变为”帝王历2535年”</li><li>1971年在波斯波利斯举办极度奢华的”波斯帝国2500年庆典”，从法国空运鹅肝酱和上千瓶名酒，沙漠里连夜搭了50多座带空调的豪华帐篷，耗资上亿美元</li></ul><p>这些举措在宗教群体看来，不是”现代化”，而是<strong>文化灭绝</strong>——是对伊朗伊斯兰身份的系统性否定。什叶派宗教学者将纪年改革视为对伊斯兰教的公开否定，称其为”蒙昧时代的复兴”。</p><p><strong>巴列维同时在经济上制造了不平等，在政治上消灭了参与渠道，在文化上否定了多数人的身份认同——他同时在三个方向上制造了敌人。</strong></p><h3 id="第三章-亨廷顿的预言——危险是如何积累的" tabindex="-1">第三章：亨廷顿的预言——危险是如何积累的 <a class="header-anchor" href="#第三章-亨廷顿的预言——危险是如何积累的" aria-label="Permalink to &quot;第三章：亨廷顿的预言——危险是如何积累的&quot;">​</a></h3><p>要理解为什么这些改革没有带来稳定反而催生了革命，我们需要引入政治学家塞缪尔·亨廷顿在1968年提出的经典分析框架。</p><h3 id="核心公式" tabindex="-1">核心公式 <a class="header-anchor" href="#核心公式" aria-label="Permalink to &quot;核心公式&quot;">​</a></h3><p>亨廷顿在《变化社会中的政治秩序》中提出了一个简洁而深刻的命题：</p><blockquote><p><strong>社会动员 ÷ 经济发展 = 社会颓丧（需求与满足的差距）</strong> <strong>社会颓丧 ÷ 流动机会 = 政治参与</strong> <strong>政治参与 ÷ 政治制度化 = 政治动乱</strong></p></blockquote><p>翻译成白话就是：<strong>现代化催生了人们对更好生活的期望，但满足这些期望的能力跟不上期望增长的速度，于是产生了”社会颓丧感”。当这种颓丧感无法通过正常的社会流动来疏导时，人们就会转向政治领域寻求改变。如果政治制度无法容纳这种参与需求，就会爆发政治动乱。</strong></p><p>亨廷顿的核心结论是：<strong>“现代性有助于政治稳定，而现代化却孕育了不稳定。”</strong> 换句话说，已经现代化的社会和传统社会都趋向于稳定，而处于现代化过程中的社会则必然滋长政治不稳定倾向。</p><p>（需要说明的是，这一框架带有明显的结构决定论色彩，它解释不了革命的偶然性与个人抉择——但巴列维治下的伊朗几乎是它最贴合的样本。）</p><h3 id="巴列维伊朗的完美案例" tabindex="-1">巴列维伊朗的完美案例 <a class="header-anchor" href="#巴列维伊朗的完美案例" aria-label="Permalink to &quot;巴列维伊朗的完美案例&quot;">​</a></h3><p>把亨廷顿的公式套用到巴列维的伊朗上，每一个变量都精确对应：</p><p><strong>社会动员的爆炸：</strong> 白色革命的教育普及（识字率从15%升至47%）、城市化（从约30%升至约54%）、工业化（制造业就业人口急剧扩大）、大众传媒推广，将数百万此前被排斥在政治之外的社会群体——农民、工人、城市贫民、妇女——动员了起来。他们第一次产生了”我应该是国家的主人”的意识。</p><p><strong>流动机会的匮乏：</strong> 然而，经济繁荣的红利几乎全部流向了王室、权贵和与政权关联的商业网络。底层民众——尤其是涌入城市的破产农民——发现自己被困在棚户区的铁棚屋里，既无法回到农村（土地已经卖掉或荒废），也无法在城市中找到体面的工作。青年失业率超过25%，通货膨胀率一度突破30%。</p><p><strong>政治参与需求的爆发：</strong> 当经济流动渠道被堵死时，人们自然转向政治领域寻求改变。他们要求参与决策、要求公平分配、要求基本的政治权利。</p><p><strong>政治制度化的严重滞后：</strong> 但巴列维提供的政治参与渠道是什么？1975年之后，连形式上的两党制都被取消了，只剩下一个强制入党的御用工具。议会形同虚设，萨瓦克监视一切，任何独立政治活动都被镇压。<strong>政治参与的爆炸与政治制度的封闭之间，形成了致命的落差。</strong></p><p>亨廷顿的公式解释了危险如何积累：<strong>当一个社会的经济现代化催生了政治参与的需求，而政治体制的封闭使得这种需求无法通过制度渠道释放时，革命的条件就成熟了。</strong></p><p>但这里留着一个亨廷顿没有回答的问题——<strong>条件成熟，不等于此刻爆发。为什么是1978年，而不是1970年或1990年？</strong></p><h3 id="第四章-1978——从-危险-到-引爆" tabindex="-1">第四章：1978——从”危险”到”引爆” <a class="header-anchor" href="#第四章-1978——从-危险-到-引爆" aria-label="Permalink to &quot;第四章：1978——从”危险”到”引爆”&quot;">​</a></h3><p>亨廷顿解释的是长期积累，而解释”时机”需要另一个工具：<strong>詹姆斯·戴维斯在1962年提出的”J曲线”理论</strong>。</p><h3 id="j曲线-革命发生在期望与满足的落差最大处" tabindex="-1">J曲线：革命发生在期望与满足的落差最大处 <a class="header-anchor" href="#j曲线-革命发生在期望与满足的落差最大处" aria-label="Permalink to &quot;J曲线：革命发生在期望与满足的落差最大处&quot;">​</a></h3><p>戴维斯的命题同样简洁：</p><blockquote><p>革命最可能发生的时刻，不是长期停滞、民不聊生的时候——那种状态人们早已麻木，忍耐力反而最强。革命最可能发生在<strong>一段持续上升的期望之后，突然遭遇急剧的满足下滑</strong>。</p></blockquote><p>把期望与满足画成曲线：一段长时间的共同上升，然后满足感突然掉头向下，而期望还沿着原来的斜率往上冲——两者的缺口，就是革命的引信。</p><p>巴列维伊朗恰恰完整地走完了这条曲线。</p><h3 id="_1974—1977-从顶点到掉头" tabindex="-1">1974—1977：从顶点到掉头 <a class="header-anchor" href="#_1974—1977-从顶点到掉头" aria-label="Permalink to &quot;1974—1977：从顶点到掉头&quot;">​</a></h3><p><strong>顶点（1974—1975）：</strong> 油价暴涨，国库充盈，”十年内成为世界第五大工业国”的许诺被反复宣讲。整个社会的期望被推到了天花板——人们相信好日子会一直加速。</p><p><strong>掉头（1976—1977）：</strong> 油价停滞，而此前超发的货币和失控的开支开始反噬。通胀率一度突破25%—30%，实际工资下降，青年失业率超过25%。政府被迫转向紧缩。</p><p><strong>最致命的一步，是紧缩以”反投机倒把运动”的形式落到巴扎商人头上。</strong> 巴扎是伊朗传统商业的心脏，控制着国内贸易的三分之二。政府把通胀的锅甩给”投机商”，大批商人被罚款、封店、判刑、流放。<strong>这一步，把一个原本最保守、最不愿参与政治的阶层，直接推向了教士阶层。</strong> 巴扎商人与教士之间的同盟——资金与组织、钱包与讲坛——在这个时刻正式成型。</p><p><strong>松动（1977）：</strong> 卡特政府推行人权外交，巴列维为换取美国支持，被迫放松控制：允许国际红十字会探视监狱，允许部分政治犯辩护，知识分子的公开信开始出现。讽刺的是，<strong>高压的每一次松动，都成了积压已久的不满喷涌的出口。</strong></p><h3 id="_1978-四十天一次的全国心跳" tabindex="-1">1978：四十天一次的全国心跳 <a class="header-anchor" href="#_1978-四十天一次的全国心跳" aria-label="Permalink to &quot;1978：四十天一次的全国心跳&quot;">​</a></h3><p>进入1978年，事件以惊人的节奏自我加速：</p><ul><li><strong>1月，库姆血案。</strong> 官方媒体刊登文章攻击霍梅尼，库姆神学院学生上街抗议，军队开枪，数十人死亡。</li><li><strong>四十天周期启动。</strong> 什叶派有在死者第40天举行哀悼仪式的传统（chehelom）。于是每到第40天，就有新的悼念活动；新的悼念活动又造成新的死者；新的死者又开启下一个40天。<strong>一个宗教仪轨，变成了一台自动的、全国性的动员机器。</strong> 这一年，伊朗社会就像被装上了一个节拍器。</li><li><strong>8月，雷克斯影院纵火。</strong> 阿巴丹一家电影院被纵火，约400人葬身火海。锁着的出口门与迟迟不来的消防队，让公众几乎一致认定这是萨瓦克所为。无论真相如何，它彻底摧毁了政府的公信力。</li><li><strong>9月8日，黑色星期五。</strong> 军队在德黑兰贾勒广场向示威者开枪，死亡人数至今争议，但流血使妥协不再可能。</li><li><strong>10—12月，石油工人罢工。</strong> 这是决定性的一击——石油停摆，国库断流，军队发不出军饷。一个靠石油美元维系的政权，被抽走了它的血液。</li><li><strong>12月，穆哈兰姆月。</strong> 百万级人潮涌上德黑兰街头。军队开始拒绝开枪。</li></ul><p>到1979年1月16日，巴列维登上飞机离开伊朗，此后再未回来。</p><p><strong>亨廷顿解释了火药如何堆积，J曲线解释了火花为什么在那一刻划下。</strong> 两条曲线叠加，才完整回答了标题里的那个问题。</p><h3 id="第五章-所有被排斥的力量汇入同一个方向" tabindex="-1">第五章：所有被排斥的力量汇入同一个方向 <a class="header-anchor" href="#第五章-所有被排斥的力量汇入同一个方向" aria-label="Permalink to &quot;第五章：所有被排斥的力量汇入同一个方向&quot;">​</a></h3><h3 id="革命联盟的-最大公约数" tabindex="-1">革命联盟的”最大公约数” <a class="header-anchor" href="#革命联盟的-最大公约数" aria-label="Permalink to &quot;革命联盟的”最大公约数”&quot;">​</a></h3><p>1979年革命不是一场单一力量发动的运动，而是一场典型的“<strong>最大公约数联盟</strong>”。参与推翻巴列维的力量包括：</p><ul><li><strong>什叶派教士阶层</strong>：要恢复宗教权力，土地改革和世俗化触犯了他们的经济基础和文化权威</li><li><strong>巴扎商人</strong>：控制国内贸易三分之二，因政府的反投机倒把运动利益受损，与教士结成政治同盟</li><li><strong>左翼政党</strong>（人民党、人民圣战者组织、人民敢死队等）：要建世俗社会主义共和国</li><li><strong>自由派知识分子</strong>（巴扎尔甘的”自由运动”等）：要建议会民主制</li><li><strong>工人和石油产业从业者</strong>：要劳工权益</li><li><strong>破产农民和城市贫民</strong>：要土地和面包</li></ul><p>这些力量的政治目标<strong>根本对立</strong>——左翼要社会主义，自由派要西式民主，教士要神权国家——但他们有一个共同的敌人：巴列维。</p><h3 id="为什么教士阶层成了最终的赢家" tabindex="-1">为什么教士阶层成了最终的赢家？ <a class="header-anchor" href="#为什么教士阶层成了最终的赢家" aria-label="Permalink to &quot;为什么教士阶层成了最终的赢家？&quot;">​</a></h3><p>在所有参与革命的力量中，教士阶层之所以最终胜出，不是因为他们代表了多数人的意愿，而是因为<strong>他们是唯一拥有现成组织网络的力量</strong>。</p><p>左翼政党被萨瓦克系统性摧毁——人民党在1953年政变后遭受毁灭性打击，被迫转入地下，中苏决裂后又经历了多次内部分裂，到1970年代已经元气大伤。自由派知识分子没有群众基础。工人阶级缺乏独立的组织架构。</p><p>而教士阶层拥有：遍布全国的清真寺网络（天然的组织和通信系统）、独立的宗教税收（胡姆斯和天课，不依赖国家财政）、经学院体系（持续培养组织人才）、以及什叶派”殉道叙事”的文化传统（为牺牲赋予意义）。</p><blockquote><p><strong>当所有其他政治力量都被萨瓦克消灭后，清真寺成了唯一还能运作的公共空间。</strong></p></blockquote><p>革命的火种不是在政治机构中保存的，而是在宗教机构中保存的——<strong>这恰恰是巴列维政治封闭政策最深刻的反讽：他为了消灭反对派而关闭了所有公共空间，结果把唯一的公共空间留给了自己的掘墓人。</strong></p><h3 id="结语-被垄断的进步" tabindex="-1">结语：被垄断的进步 <a class="header-anchor" href="#结语-被垄断的进步" aria-label="Permalink to &quot;结语：被垄断的进步&quot;">​</a></h3><p>巴列维的故事最终指向一个令人不安的结论：</p><blockquote><p><strong>他用现代化的手段制造了现代化的需求，却用前现代的方式回应这些需求。</strong></p></blockquote><p>经济改革让人们产生了”我应该是国家的主人”的意识，政治体制却告诉他们”你什么都不是”。文化改革让人们感到”我的身份被否定了”，却没有提供任何替代性的认同。最终，所有被排斥的力量——无论动机多么不同——汇入了同一个方向：推翻巴列维。</p><p>历史从不反对进步，反对的只是被垄断的进步。当土地可以重新分配，尊严却无法匹配；当制度可以现代化，权力却不可触碰——改革就不再是通往稳定的道路，而是通往革命的加速器。</p><p>到这里，还有一个问题只能提出、无法在这里回答：<strong>同样是激进的世俗化改革，凯末尔的土耳其延续了近百年，巴列维的伊朗十六年就被连根拔起。</strong> 这是运气，还是条件？我们在本系列第四篇专门拆解。</p><p>而巴列维留下的”最大公约数联盟”，从成立的那一刻起就埋下了互相清洗的种子。左翼、自由派、教士因为共同的敌人站在一起，却在敌人消失的第二天发现：他们之间的分歧，比对巴列维的仇恨更深。</p><p>巴列维用十六年证明了”改革可能催生革命”。接下来，霍梅尼将用更短的时间证明另一件事：<strong>革命同样可以吞噬革命者。</strong></p><p><em>（本系列下一篇：《霍梅尼的背叛》——革命联盟如何被逐一清洗，”自由民主”的承诺如何变成神权专制的现实。）</em></p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2083165332286468812" target="_blank" rel="noreferrer">查看原文</a></p></blockquote>',112)])])}const u=r(n,[["render",s]]);export{c as __pageData,u as default};
